const people=[{name:'李白',years:'701—762',title:'诗仙 · 浪漫的远行者',desc:'从蜀地走向远方，在山水与理想之间，留下一个自由而热烈的身影。',tags:['浪漫主义','山水漫游','盛唐气象'],quote:'轻舟已过万重山',stops:[
['725年','荆门山',111.47,30.42,'今湖北宜都西北长江南岸','渡荆门送别','渡远荆门外，来从楚国游。\n山随平野尽，江入大荒流。\n月下飞天镜，云生结海楼。\n仍怜故乡水，万里送行舟。','离蜀远游，山川初开','青年李白离开蜀地，乘舟东下。此处荆门指宜都一带的荆门山。高山渐远，平野展开；壮阔的景物中，也藏着初离故乡的依恋。','山水','“送行舟”的是故乡水，还是诗人的情感？找出拟人手法。'],
['约730年','黄鹤楼',114.3,30.55,'今湖北武汉','黄鹤楼送孟浩然之广陵','故人西辞黄鹤楼，\n烟花三月下扬州。\n孤帆远影碧空尽，\n唯见长江天际流。','一场送别，满江春色','李白在黄鹤楼送孟浩然前往广陵。“烟花”是春日繁花与迷蒙烟柳；去扬州的是孟浩然，不能据此把扬州记作李白这一站的目的地。','繁花','“孤帆”渐远后，诗人为何还望着长江？'],
['755年','庐山',115.99,29.55,'今江西九江','望庐山瀑布（其二）','日照香炉生紫烟，\n遥看瀑布挂前川。\n飞流直下三千尺，\n疑是银河落九天。','把山水写成想象','以香炉峰的云烟和瀑布为景，诗人把眼前飞瀑想象成天上银河。此诗系年有争议，此处取天宝十四载说作演示。','瀑布','“三千尺”可以拿来测量瀑布吗？夸张带来了什么感受？'],
['759年','白帝城',109.58,31.04,'今重庆奉节','早发白帝城','朝辞白帝彩云间，\n千里江陵一日还。\n两岸猿声啼不住，\n轻舟已过万重山。','遇赦之后，轻舟东下','李白流放夜郎途中遇赦，从白帝城乘舟向江陵进发。轻快的节奏，传达出重获自由的喜悦。动画表现诗中的舟行意象。','轻舟','同是写江水，《渡荆门送别》与此诗的心境有何不同？']]},
{name:'杜甫',years:'712—770',title:'诗圣 · 山河的记录者',desc:'从乱世中的长安到成都草堂，他把个人的漂泊，写成对天下苍生的牵挂。',tags:['现实主义','家国情怀','安史之乱'],quote:'感时花溅泪',stops:[
['757年','长安',108.94,34.26,'今陕西西安','春望','国破山河在，城春草木深。\n感时花溅泪，恨别鸟惊心。\n烽火连三月，家书抵万金。\n白头搔更短，浑欲不胜簪。','乱世长安，春景含悲','安史之乱中，杜甫身陷被叛军占领的长安。春花与鸟鸣未能排遣忧愁，反而触动他对国事和亲人的牵挂。','烽火','花与鸟本是美景，为什么会让人落泪、惊心？'],
['761年','成都',104.07,30.67,'今四川成都','茅屋为秋风所破歌（节选）','安得广厦千万间，\n大庇天下寒士俱欢颜！\n风雨不动安如山。','草堂风雨，心系天下','杜甫在成都浣花溪畔暂居。秋风破屋、雨夜难眠，他从自身的困境想到天下寒士的处境。','风雨','从“吾庐”到“天下寒士”，诗人的关怀发生了怎样的变化？'],
['767年','夔州',109.46,31.02,'今重庆奉节','登高','风急天高猿啸哀，渚清沙白鸟飞回。\n无边落木萧萧下，不尽长江滚滚来。\n万里悲秋常作客，百年多病独登台。\n艰难苦恨繁霜鬓，潦倒新停浊酒杯。','暮年登高，江流不尽','旅居夔州的杜甫，在秋日登高。落木与长江构成辽阔景象，映照他漂泊、多病的晚年心境。','秋叶','“无边”与“不尽”，如何把眼前之景推向更大的时空？'],
['768年','岳阳',113.1,29.38,'今湖南岳阳','登岳阳楼','昔闻洞庭水，今上岳阳楼。\n吴楚东南坼，乾坤日夜浮。\n亲朋无一字，老病有孤舟。\n戎马关山北，凭轩涕泗流。','一叶孤舟，仍望关山','离开夔州后，杜甫辗转至岳阳。面对洞庭湖，他既感个人的孤苦，也为北方未息的战事流泪。','轻舟','这首诗如何把壮阔山河、个人身世和国家命运联系起来？']]},
{name:'苏轼',years:'1037—1101',title:'东坡 · 风雨中的旷达',desc:'在宦海起伏中，始终保有发现日常之美的目光。山水、风雨与明月，都能成为人生的回声。',tags:['豪放词风','旷达乐观','人生哲思'],quote:'一蓑烟雨任平生',stops:[
['1073年','杭州',120.15,30.25,'今浙江杭州','饮湖上初晴后雨（其二）','水光潋滟晴方好，\n山色空蒙雨亦奇。\n欲把西湖比西子，\n淡妆浓抹总相宜。','晴雨西湖，各有其美','任杭州通判期间，苏轼欣赏西湖晴雨变换，以西施比喻西湖，把自然风光写得亲切而灵动。','山水','“晴方好”和“雨亦奇”，体现了怎样的审美态度？'],
['1076年','密州',119.41,36.0,'今山东诸城','水调歌头（节选）','人有悲欢离合，\n月有阴晴圆缺，\n此事古难全。\n但愿人长久，\n千里共婵娟。','千里明月，遥寄手足','中秋夜，苏轼在密州饮酒，怀念弟弟苏辙。词前小序写“兼怀子由”，从个人的离愁走向对所有离人的祝愿。','明月','明月为什么能把相隔千里的人联系起来？'],
['1082年','黄州',114.88,30.45,'今湖北黄冈','定风波（节选）','莫听穿林打叶声，\n何妨吟啸且徐行。\n竹杖芒鞋轻胜马，谁怕？\n一蓑烟雨任平生。','途中遇雨，徐行不惧','乌台诗案后，苏轼被贬黄州。一次沙湖道中遇雨，他把生活中的风雨化为面对人生挫折的思考。','风雨','词中的“风雨”，只指天气吗？'],
['1084年','庐山',115.99,29.55,'今江西九江','题西林壁','横看成岭侧成峰，\n远近高低各不同。\n不识庐山真面目，\n只缘身在此山中。','转换视角，看见不同','离开黄州后，苏轼游庐山。同一座山因观看的位置不同而呈现不同面貌，引出关于认识事物的思考。','山水','请举一个生活中“身在此山中”的例子。']]}
];
