const withinYear={'lb-emei':1,'lb-jingmen':2,'df-kezhi':2,'df-maowu':8,'ss-meng':1,'ss-lie':9};const sortYear=s=>(s[11].role==='地点待考'?9999:parseInt(s[0].match(/\d+/)?.[0]||'9999'))*100+(withinYear[s[11].id]||5);people.forEach(p=>p.stops.sort((a,b)=>sortYear(a)-sortYear(b)));
